/**
 * Relative duration strings for reminder schedules (`every` / `delay`).
 * Thin wrapper around the `ms` package (`30s`, `5m`, `2h`, `1d`, …).
 */
import ms from "ms";
/** Parse a relative duration into milliseconds. Throws on invalid input. */
export function parseDuration(input) {
    if (typeof input === "number") {
        if (!Number.isFinite(input) || input < 0) {
            throw new Error(`Invalid duration ms: ${input}`);
        }
        return Math.floor(input);
    }
    const trimmed = input.trim();
    if (trimmed === "") {
        throw new Error("Invalid duration: empty string");
    }
    if (/^\d+$/.test(trimmed)) {
        return Number(trimmed);
    }
    // oxlint-disable-next-line typescript/no-unsafe-type-assertion -- ms.StringValue is a template-literal brand; parseDuration rejects what ms cannot parse
    const parsed = ms(trimmed);
    if (typeof parsed !== "number" || !Number.isFinite(parsed) || parsed < 0) {
        throw new Error(`Invalid duration "${input}": expected e.g. "30s", "5m", "2h", "1d"`);
    }
    return Math.floor(parsed);
}
export function isValidDuration(input) {
    try {
        parseDuration(input);
        return true;
    }
    catch {
        return false;
    }
}
